import { AxisScale } from '@visx/axis';
import { scaleTime } from '@visx/scale';

import { Annotation } from '../../core/components/annotations-timeseries/types/annotations.js';

export const getScale = (
  data: Annotation[],
  width: number,
): AxisScale<number> => {
  const domain = getDomain(data);

  return scaleTime({
    domain,
    range: [0, width],
  });
};

export const getDomain = (data: Annotation[]) => {
  const timestampsSet = new Set<number>();

  data.forEach((datapoint) => {
    timestampsSet.add(datapoint.start.getTime());
    if (datapoint.end) {
      timestampsSet.add(datapoint.end.getTime());
    }
  });

  const timestamps = Array.from(timestampsSet);

  return [Math.min(...timestamps), Math.max(...timestamps)];
};
